#!/bin/bash

# ─── Colors ─────────────────────────────────────────────────────────
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
CYAN='\033[0;36m'
PURPLE='\033[0;35m'
BOLD='\033[1m'
NC='\033[0m'

clear

echo -e "${PURPLE}${BOLD}"
echo "╔═══════════════════════════════════════════════════╗"
echo "║    HunterIsLive — Ubuntu Setup Script v1.2       ║"
echo "╠═══════════════════════════════════════════════════╣"
echo "║  YouTube : @HunterIsLive                         ║"
echo "║  GitHub  : github.com/HunterisLive-1             ║"
echo "║  Website : getmaya.online                        ║"
echo "╚═══════════════════════════════════════════════════╝"
echo -e "${NC}"
sleep 1

# ─── Banner Name ─────────────────────────────────────────────────────
CONFIG_FILE="/storage/emulated/0/hunter_config.txt"
if [ -f "$CONFIG_FILE" ]; then
    USER_BANNER_NAME=$(cat "$CONFIG_FILE")
    echo -e "${GREEN}✓ Banner name Termux se mila: ${BOLD}${USER_BANNER_NAME}${NC}"
else
    echo -e "${CYAN}${BOLD}Apna naam enter karo (banner ke liye, space mat use karna):${NC}"
    printf "➜ Your Name: "
    read USER_BANNER_NAME
    [ -z "$USER_BANNER_NAME" ] && USER_BANNER_NAME="Hunter"
fi
echo ""
sleep 1

# ─── Step 1: System Update ───────────────────────────────────────────
echo -e "${CYAN}${BOLD}[1/8] Ubuntu update & upgrade...${NC}"
export DEBIAN_FRONTEND=noninteractive
apt update -y && apt upgrade -y

# ─── Step 2: Core Packages ───────────────────────────────────────────
echo -e "${CYAN}${BOLD}[2/8] Core packages install ho rahe hain...${NC}"
apt install -y \
    git curl wget zip unzip tar nano vim \
    figlet ruby zsh \
    python3 python3-pip python3-venv \
    nodejs npm \
    build-essential ca-certificates

echo -e "${CYAN}      lolcat install ho raha hai...${NC}"
gem install lolcat

# ─── Step 3: Python Tools ────────────────────────────────────────────
echo -e "${CYAN}${BOLD}[3/8] Python tools install ho rahe hain...${NC}"
# Ubuntu mein pre-built wheels available hain, fastapi bhi chalega
pip3 install requests httpx flask fastapi uvicorn python-dotenv rich 2>/dev/null \
  || pip3 install requests httpx flask uvicorn python-dotenv rich

echo -e "${CYAN}      uv install ho raha hai...${NC}"
wget -qO- https://astral.sh/uv/install.sh | sh 2>/dev/null \
  && echo -e "${GREEN}      ✓ uv installed${NC}" \
  || echo -e "${YELLOW}      uv skip${NC}"

# ─── Step 4: Node.js Global Tools ────────────────────────────────────
echo -e "${CYAN}${BOLD}[4/8] Node.js global tools...${NC}"
npm install -g nodemon pm2 serve 2>/dev/null || true

# ─── Step 5: Oh My Zsh + P10k + Plugins ─────────────────────────────
echo -e "${CYAN}${BOLD}[5/8] Oh My Zsh + Powerlevel10k + Plugins...${NC}"

if [ ! -d "$HOME/.oh-my-zsh" ]; then
    sh -c "$(wget -qO- https://raw.githubusercontent.com/ohmyzsh/ohmyzsh/master/tools/install.sh)" "" --unattended
else
    echo -e "${YELLOW}      Oh My Zsh already installed — skip${NC}"
fi

P10K_DIR="${HOME}/.oh-my-zsh/custom/themes/powerlevel10k"
if [ ! -d "$P10K_DIR" ]; then
    git clone --depth=1 https://github.com/romkatv/powerlevel10k.git "$P10K_DIR"
else
    echo -e "${YELLOW}      Powerlevel10k already installed — skip${NC}"
fi

AS_DIR="${HOME}/.oh-my-zsh/custom/plugins/zsh-autosuggestions"
if [ ! -d "$AS_DIR" ]; then
    git clone https://github.com/zsh-users/zsh-autosuggestions "$AS_DIR"
else
    echo -e "${YELLOW}      zsh-autosuggestions already installed — skip${NC}"
fi

# ─── Step 6: Configure .zshrc ────────────────────────────────────────
echo -e "${CYAN}${BOLD}[6/8] Ubuntu .zshrc configure ho raha hai...${NC}"

rm -f ~/.cache/p10k-instant-prompt-*.zsh 2>/dev/null

cat > ~/.zshrc << 'UBUNTU_STATIC'
# ═══════════════════════════════════════════════════
#  HunterIsLive — Ubuntu ZSH Config v1.2
#  YouTube : @HunterIsLive | getmaya.online
# ═══════════════════════════════════════════════════

# MUST BE FIRST — P10k warning fix
typeset -g POWERLEVEL9K_INSTANT_PROMPT=off

if [[ -r "${XDG_CACHE_HOME:-$HOME/.cache}/p10k-instant-prompt-${(%):-%n}.zsh" ]]; then
  source "${XDG_CACHE_HOME:-$HOME/.cache}/p10k-instant-prompt-${(%):-%n}.zsh"
fi

export ZSH="$HOME/.oh-my-zsh"
ZSH_THEME="powerlevel10k/powerlevel10k"
plugins=(git zsh-autosuggestions)
source $ZSH/oh-my-zsh.sh

# ===== ALIASES — UBUNTU =====
alias c='clear'
alias update='apt update && apt upgrade -y'
alias py='python3'
alias pip='pip3'
alias storage='cd /storage/emulated/0'
alias coding='cd /storage/emulated/0/coding'
alias activate='source ~/venv/bin/activate'

export PATH="$HOME/.cargo/bin:$PATH"
export PATH="$HOME/.local/bin:$PATH"
UBUNTU_STATIC

cat >> ~/.zshrc << UBUNTU_DYNAMIC

# ===== UBUNTU BANNER =====
clear
echo -e "\e[1;35m"
figlet -c -f big "$USER_BANNER_NAME" | lolcat
echo -e "\e[1;33m      [ Ubuntu Container ]\e[0m"
echo -e "\e[0m"
# =========================

[[ ! -f ~/.p10k.zsh ]] || source ~/.p10k.zsh
UBUNTU_DYNAMIC


# ─── Step 7: .p10k.zsh — pre-configured ─────────────────────────────
echo -e "${CYAN}${BOLD}[7/8] .p10k.zsh configure ho raha hai (no wizard!)...${NC}"
echo '' | base64 -d > ~/.p10k.zsh \
  && echo -e "${GREEN}      ✓ .p10k.zsh configured${NC}" \
  || echo -e "${YELLOW}      .p10k.zsh fail — run: p10k configure${NC}"

# ─── Step 8: Auto ZSH + Final ────────────────────────────────────────
echo -e "${CYAN}${BOLD}[8/8] Auto ZSH launch aur final tweaks...${NC}"

if ! grep -q "exec zsh" ~/.bashrc 2>/dev/null; then
    echo '' >> ~/.bashrc
    echo '# HunterIsLive Setup — Auto ZSH' >> ~/.bashrc
    echo '[ -z "$ZSH_VERSION" ] && exec zsh' >> ~/.bashrc
    echo -e "${GREEN}      ✓ Auto ZSH launch set${NC}"
else
    echo -e "${YELLOW}      Auto ZSH already set — skip${NC}"
fi

# ─── Done! ───────────────────────────────────────────────────────────
echo ""
echo -e "${GREEN}${BOLD}"
echo "╔═══════════════════════════════════════════════════╗"
echo "║   ✅  UBUNTU SETUP COMPLETE!                      ║"
echo "╠═══════════════════════════════════════════════════╣"
echo "║                                                   ║"
echo "║   Ab karo:                                       ║"
echo "║   → exit (Ubuntu se bahar aao)                   ║"
echo "║   → ubntu (wapas Ubuntu mein jao)                ║"
echo "║   Sirf Ubuntu banner dikhega! ✅                  ║"
echo "║                                                   ║"
echo "║   YouTube : @HunterIsLive                        ║"
echo "║   Website : getmaya.online                       ║"
echo "╚═══════════════════════════════════════════════════╝"
echo -e "${NC}"
echo -e "${YELLOW}${BOLD}exit → ubntu → enjoy! 🔥${NC}"
